import React, { useState, useEffect } from 'react';
import api from '../services/api'; // Dùng trung tâm dữ liệu ní đã viết[cite: 50]

const Orders = () => {
    const [orders, setOrders] = useState([]);

    // 4 Trạng thái thầy yêu cầu + 1 trạng thái Hủy[cite: 43]
    const statusMap = {
        0: { label: "Chờ xử lý", color: "badge-secondary" },
        1: { label: "Chờ vận chuyển", color: "badge-info" },
        2: { label: "Đang vận chuyển", color: "badge-warning" },
        3: { label: "Hoàn thành", color: "badge-success" },
        4: { label: "Đã hủy", color: "badge-danger" }
    };

    const fetchOrders = async () => {
        try {
            const res = await api.get('/orders'); // Gọi qua Gateway cổng 5000[cite: 50]
            setOrders(res.data.items || res.data);
        } catch (err) { console.log("Lỗi tải đơn hàng"); }
    };

    useEffect(() => { fetchOrders(); }, []);

    const updateStatus = async (id, newStatus) => {
        try {
            await api.put(`/orders/${id}/status`, { status: parseInt(newStatus) });
            alert("Đã chuyển trạng thái đơn hàng! 🚚");
            fetchOrders();
        } catch (err) { alert("Không cập nhật được trạng thái!"); }
    };

    return (
        <>
            {/* Phần tiêu đề trang giúp căn chỉnh lề chuẩn AdminLTE */}
            <div className="content-header">
                <div className="container-fluid">
                    <div className="row mb-2">
                        <div className="col-sm-6">
                            <h1 className="m-0">Danh sách hóa đơn</h1>
                        </div>
                    </div>
                </div>
            </div>

            {/* Nội dung chính đưa vào section để Sidebar không đè lên */}
            <section className="content">
                <div className="container-fluid">
                    <div className="card">
                        <div className="card-body table-responsive p-0">
                            <table className="table table-hover text-nowrap">
                                <thead>
                                    <tr>
                                        <th>ID</th>
                                        <th>Khách hàng</th>
                                        <th>Tổng tiền</th>
                                        <th>Trạng thái hiện tại</th>
                                        <th>Xử lý chuyển trạng thái</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {orders.length > 0 ? (
                                        orders.map((order) => (
                                            <tr key={order.id}>
                                                <td>{order.id}</td>
                                                <td>{order.userId}</td>
                                                <td>${order.totalAmount?.toFixed(2)}</td>
                                                <td>
                                                    <span className={`badge ${statusMap[order.status]?.color} p-2 text-white`}>
                                                        {statusMap[order.status]?.label}
                                                    </span>
                                                </td>
                                                <td>
                                                    <select
                                                        className="form-control form-control-sm"
                                                        style={{ width: '160px' }}
                                                        value={order.status}
                                                        onChange={(e) => updateStatus(order.id, e.target.value)}
                                                    >
                                                        <option value="0">Chờ xử lý</option>
                                                        <option value="1">Chờ vận chuyển</option>
                                                        <option value="2">Đang vận chuyển</option>
                                                        <option value="3">Hoàn thành</option>
                                                        <option value="4">Hủy đơn</option>
                                                    </select>
                                                </td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan="5" className="text-center py-4">Chưa có đơn hàng nào.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </section>
        </>
    );
};
export default Orders;
